-- ============================================================
-- Sample Sales Database
-- Generated: 2026-02-02
-- ============================================================

DROP DATABASE IF EXISTS sample_sales;
CREATE DATABASE sample_sales;
USE sample_sales;

-- ------------------------------------------------------------
-- Table: Store_Sales
-- ------------------------------------------------------------
DROP TABLE IF EXISTS Store_Sales;
CREATE TABLE Store_Sales (
  id               INT AUTO_INCREMENT PRIMARY KEY,
  Transaction_Date DATE,
  Store_ID         INT,
  ProdNum         VARCHAR(255),
  Sale_Amount      DECIMAL(10,2)
  -- , Category         VARCHAR(255) DEFAULT '0'
);


-- ------------------------------------------------------------
-- Table: Online_Sales
-- ------------------------------------------------------------
DROP TABLE IF EXISTS Online_Sales;
CREATE TABLE Online_Sales (
  id INT AUTO_INCREMENT PRIMARY KEY,
  Date DATE,
  ProdNum VARCHAR(255),
  SalesTotal DECIMAL(10,2),
  ShiptoState VARCHAR(255)
);


-- ------------------------------------------------------------
-- Table: Products
-- ------------------------------------------------------------
DROP TABLE IF EXISTS Products;
CREATE TABLE Products (
  ProdNum VARCHAR(255) PRIMARY KEY,
  Product VARCHAR(255),
  Categoryid INT,
  Subcategoryid VARCHAR(255)
);


-- ------------------------------------------------------------
-- Table: Inventory_Categories
-- ------------------------------------------------------------
DROP TABLE IF EXISTS Inventory_Categories;
CREATE TABLE Inventory_Categories (
  Categoryid INT PRIMARY KEY,
  Category VARCHAR(255),
  Description VARCHAR(255)
);


-- ------------------------------------------------------------
-- Table: Inventory_Subategories
-- ------------------------------------------------------------
DROP TABLE IF EXISTS Inventory_Subategories;
CREATE TABLE Inventory_Subategories (
  Subcategoryid VARCHAR(255) PRIMARY KEY,
  Categoryid INT,
  Subcategory VARCHAR(255)
);


-- ------------------------------------------------------------
-- Table: Store_Locations
-- ------------------------------------------------------------
DROP TABLE IF EXISTS Store_Locations;
CREATE TABLE Store_Locations (
  StoreLocation VARCHAR(255),
  State VARCHAR(255),
  Store_ID INT PRIMARY KEY
);


-- ------------------------------------------------------------
-- Table: Management
-- ------------------------------------------------------------
DROP TABLE IF EXISTS Management;
CREATE TABLE Management (
  id INT AUTO_INCREMENT PRIMARY KEY,
  Region VARCHAR(255),
  RegionalDirector VARCHAR(255),
  State VARCHAR(255),
  SalesManager VARCHAR(255)
);


-- ------------------------------------------------------------
-- Table: Shipper_List
-- ------------------------------------------------------------
DROP TABLE IF EXISTS Shipper_List;
CREATE TABLE Shipper_List (
  id INT AUTO_INCREMENT PRIMARY KEY,
  ShiptoState VARCHAR(255),
  PreferredShipper VARCHAR(255),
  VolumeDiscount DECIMAL(10,2)
);



